def count_binary_seq(n):
    if n == 0:
        return 1
    count = 0
    for i in range(2**(n-1)):
        seq = format(i, f'0{n-1:b}')
        if seq.count('1') == (2**n - int(seq, 2)).count('1'):
            count += 1
    return count * 2
